CREATE TABLE IF NOT EXISTS audit_events (id bigserial PRIMARY KEY, audit_reference varchar(40) NOT NULL UNIQUE, actor_id varchar(100), actor_role varchar(30), customer_number varchar(30), action varchar(30) NOT NULL, result varchar(20) NOT NULL, entity_type varchar(50) NOT NULL, entity_reference varchar(100), description varchar(2000), source_ip varchar(45), created_at timestamp NOT NULL); CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_events(actor_id); CREATE INDEX IF NOT EXISTS idx_audit_customer ON audit_events(customer_number); CREATE INDEX IF NOT EXISTS idx_audit_reference ON audit_events(entity_reference); CREATE INDEX IF NOT EXISTS idx_audit_created ON audit_events(created_at);
